css:
*{margin:0;padding:0;box-sizing:border-box}
:root{
 --ink:#070a0e; --ink2:#0d1319; --char:#121c25; --char2:#18242e; --char3:#1f2f3b;
 --blue:#0a63f5; --blue-l:#4f94ff; --blue-d:#0a3fb0;
 --red:#e21019; --red-l:#ff2a31; --red-d:#a80a11;
 --paper:#f4f7f9; --paper2:#e9eef2; --white:#fff;
 --tx:#15202a; --tx2:#55646f; --line:#e1e8ed; --line-d:#243440;
 --gut:clamp(18px,5vw,56px); --rad:14px; --maxw:1280px;
 --sh:0 14px 36px -16px rgba(9,15,20,.26); --sh2:0 34px 78px -30px rgba(9,15,20,.55);
 --fd:'Archivo',system-ui,sans-serif; --fb:'Inter',system-ui,sans-serif;
}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{font-family:var(--fb);color:var(--tx);background:var(--white);line-height:1.6;overflow-x:hidden}
svg{width:18px;height:18px;flex-shrink:0}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--fd);line-height:1.04;letter-spacing:-.015em;font-weight:800}
p{overflow-wrap:anywhere}
select option{background:#0d1319;color:#fff}
.wrap{max-width:var(--maxw);margin:0 auto;padding-left:var(--gut);padding-right:var(--gut);width:100%}
.rv{animation:rvIn .85s both}
@keyframes rvIn{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
.ctr{text-align:center}

/* ============ TYPE DEVICES (Carepair language) ============ */
.eyb{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;font-size:12.5px;letter-spacing:.2em;text-transform:uppercase;color:var(--red);background:rgba(226,16,25,.09);border:1px solid rgba(226,16,25,.26);padding:8px 16px 8px 12px;border-radius:999px}
.eyb::before{content:"";width:9px;height:9px;background:var(--red);border-radius:2px;transform:rotate(45deg);animation:pip 2.2s ease-in-out infinite}
@keyframes pip{0%,100%{transform:rotate(45deg) scale(1);opacity:1}50%{transform:rotate(45deg) scale(.55);opacity:.5}}
.dark .eyb,.inkbg .eyb{color:var(--red-l);background:rgba(255,42,49,.12);border-color:rgba(255,42,49,.34)}
.dark .eyb::before,.inkbg .eyb::before{background:var(--red-l)}
.grad{background:linear-gradient(92deg,var(--blue-l),var(--blue));background-size:230% auto;-webkit-background-clip:text;background-clip:text;color:transparent;animation:gradmove 7s linear infinite}
@keyframes gradmove{to{background-position:-230% center}}

/* ============ BUTTONS ============ */
.btn{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:800;border-radius:10px;padding:16px 28px;font-size:15px;letter-spacing:.03em;cursor:pointer;transition:.22s;border:0;white-space:nowrap;position:relative;overflow:hidden;text-transform:uppercase}
.btn svg{width:17px;height:17px}
.btn::after{content:"";position:absolute;top:0;left:-130%;width:55%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.4),transparent);transform:skewX(-18deg);transition:left .65s ease}
.btn:hover::after{left:170%}
.btn-r{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;box-shadow:0 16px 32px -12px rgba(226,16,25,.75)}
.btn-r:hover{transform:translateY(-3px);box-shadow:0 22px 44px -12px rgba(226,16,25,.9)}
.btn-gh{background:rgba(255,255,255,.07);color:#fff;border:1.5px solid rgba(255,255,255,.3)}
.btn-gh:hover{background:rgba(255,255,255,.16);border-color:#fff;transform:translateY(-3px)}
.btn-dk{background:var(--ink);color:#fff}
.btn-dk:hover{background:#000;transform:translateY(-3px)}
.btn-lt{background:#fff;color:var(--ink);box-shadow:var(--sh)}
.btn-lt:hover{transform:translateY(-3px)}

/* ============ ANGLED EDGES (replaces wavy dividers) ============ */
.edge{position:relative;height:clamp(40px,4.6vw,70px);background:var(--to);line-height:0;overflow:hidden}
.edge::before{content:"";position:absolute;inset:0;background:var(--from);clip-path:polygon(0 0,100% 0,0 100%)}
.edge.rev::before{clip-path:polygon(0 0,100% 0,100% 100%)}
.edge::after{content:"";position:absolute;left:0;right:0;top:0;height:100%;background:linear-gradient(to bottom right,transparent calc(50% - 2px),var(--red) 50%,transparent calc(50% + 2px));opacity:.85}
.edge.rev::after{background:linear-gradient(to bottom left,transparent calc(50% - 2px),var(--red) 50%,transparent calc(50% + 2px))}

/* ============ UTIL BAR ============ */
.util{background:var(--ink);color:#93a4b1;font-size:13px;border-bottom:1px solid rgba(255,255,255,.07)}
.util-in{display:flex;align-items:center;justify-content:space-between;gap:14px;min-height:44px;flex-wrap:wrap}
.util .u-l{display:flex;gap:22px;align-items:center;flex-wrap:wrap}
.util .ui{display:inline-flex;align-items:center;gap:7px}
.util svg{width:15px;height:15px;color:var(--red-l)}
.util a{color:#cfdae2;font-weight:600}.util a:hover{color:var(--red-l)}
.util .u-r{color:#7d8e9b;font-weight:600;letter-spacing:.04em;text-transform:uppercase;font-size:11.5px}

/* ============ HEADER ============ */
header{position:sticky;top:0;z-index:60;background:rgba(7,10,14,.94);backdrop-filter:blur(12px);border-bottom:1px solid rgba(255,255,255,.08)}
.hdr-in{display:flex;align-items:center;gap:22px;min-height:80px}
.brand{flex-shrink:0;display:block;line-height:0}
.brand img{height:42px;width:auto;max-width:none}
.nav{display:flex;align-items:center;gap:19px;margin-left:auto}
.nav a.nl{font-weight:600;font-size:14.5px;color:#d8e0e7;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;padding:6px 0;position:relative}
.nav a.nl .ca{width:13px;height:13px;color:#86949f}
.nav a.nl::after{content:"";position:absolute;left:0;right:0;bottom:-2px;height:2px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:.25s}
.nav a.nl:hover{color:#fff}.nav a.nl:hover::after{transform:scaleX(1)}
.hdr-cta{display:inline-flex;align-items:center;gap:8px;white-space:nowrap;background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;font-weight:800;font-family:var(--fd);padding:13px 20px;border-radius:9px;font-size:13.5px;letter-spacing:.05em;text-transform:uppercase;box-shadow:0 12px 24px -12px rgba(226,16,25,.8);transition:.2s;cursor:pointer}
.hdr-cta:hover{transform:translateY(-2px)}.hdr-cta svg{width:15px;height:15px}
.burger{display:none;width:46px;height:46px;border:1px solid rgba(255,255,255,.2);border-radius:10px;cursor:pointer;align-items:center;justify-content:center;background:rgba(255,255,255,.05);margin-left:auto}
.burger span,.burger span::before,.burger span::after{content:"";position:absolute;width:22px;height:2.4px;background:#eef3f8;border-radius:2px;transition:.25s}
.burger span{position:relative}.burger span::before{top:-7px}.burger span::after{top:7px}
.m-ph{display:none}

/* ============ HERO ============ */
.hero{position:relative;background:var(--ink);color:#eaf2f6;overflow:hidden;isolation:isolate}
.hero-bg{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;animation:kb 26s ease-in-out infinite alternate}
@keyframes kb{from{transform:scale(1.02)}to{transform:scale(1.14)}}
.hero-ov{position:absolute;inset:0;z-index:-1;background:
  linear-gradient(94deg,rgba(6,10,14,.97) 0%,rgba(6,10,14,.9) 40%,rgba(6,10,14,.58) 72%,rgba(6,10,14,.8) 100%),
  radial-gradient(58% 80% at 84% 12%,rgba(10,99,245,.3),transparent 62%)}
.hero-ov::after{content:"";position:absolute;inset:0;background-image:radial-gradient(circle at 16% 46%,rgba(10,99,245,.14),transparent 58%),radial-gradient(circle at 6% 92%,rgba(226,16,25,.12),transparent 55%),linear-gradient(45deg,rgba(255,255,255,.022) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.022) 75%),linear-gradient(45deg,rgba(255,255,255,.022) 25%,transparent 25%,transparent 75%,rgba(255,255,255,.022) 75%);background-size:auto,auto,11px 11px,11px 11px;background-position:0 0,0 0,0 0,5.5px 5.5px}
.hero-in>*{min-width:0}
.hero-in{position:relative;z-index:3;display:grid;grid-template-columns:minmax(0,1.12fr) minmax(0,.88fr);gap:46px;align-items:center;padding-top:clamp(52px,6vw,78px);padding-bottom:clamp(60px,7vw,96px)}
.hero h1{font-size:clamp(37px,5.9vw,70px);color:#fff;text-transform:uppercase;margin:18px 0 0;line-height:.97}
.hero-lead{font-size:clamp(16px,1.85vw,19.5px);color:#c0cdd6;margin-top:20px;max-width:44ch}
.hero-cta{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px;align-items:center}
.hero-tr{display:flex;gap:10px 26px;flex-wrap:wrap;margin-top:28px}
.hero-tr span{display:inline-flex;align-items:center;gap:8px;font-size:13.5px;color:#b5c3cc;font-weight:600}
.hero-tr svg{width:16px;height:16px;color:var(--red-l)}
.blob{position:absolute;border-radius:50%;filter:blur(76px);pointer-events:none;z-index:0;opacity:.45;animation:drift 22s ease-in-out infinite}
.blob.b-cy{background:radial-gradient(circle,rgba(10,99,245,.95),transparent 70%)}
.blob.b-or{background:radial-gradient(circle,rgba(226,16,25,.9),transparent 70%)}
@keyframes drift{0%,100%{transform:translate(0,0) scale(1)}33%{transform:translate(28px,-30px) scale(1.14)}66%{transform:translate(-22px,20px) scale(.9)}}

/* hero visual */
.hvis{position:relative;min-width:0}
.hvis-fr{position:relative;clip-path:polygon(9% 0,100% 0,91% 100%,0 100%);overflow:hidden;aspect-ratio:4/3.3;box-shadow:var(--sh2);border:0}
.hvis-fr img{width:100%;height:100%;object-fit:cover;transition:1.2s}
.hvis:hover .hvis-fr img{transform:scale(1.06)}
.hvis-rt{position:absolute;left:-6px;bottom:28px;background:#fff;color:var(--tx);border-radius:12px;padding:13px 17px;display:flex;align-items:center;gap:12px;box-shadow:var(--sh2);z-index:2;animation:floaty 5.5s ease-in-out infinite}
.hvis-rt .st{display:flex;gap:1px;color:#f5a623}.hvis-rt .st svg{width:13px;height:13px}
.hvis-rt b{font-family:var(--fd);font-size:16px;display:block;line-height:1.1;color:var(--ink)}
.hvis-rt small{font-size:11.5px;color:var(--tx2);letter-spacing:.04em;text-transform:uppercase;font-weight:700}
@keyframes floaty{0%,100%{transform:translateY(0)}50%{transform:translateY(-7px)}}
.hvis-chip{position:absolute;right:-4px;top:16px;background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff;font-family:var(--fd);font-weight:900;font-size:12.5px;letter-spacing:.09em;text-transform:uppercase;padding:11px 16px;border-radius:9px;z-index:2;box-shadow:0 16px 32px -14px rgba(226,16,25,.9)}

/* rotating quote badge */
.spin{position:absolute;right:-18px;bottom:-26px;width:124px;height:124px;z-index:4;cursor:pointer}
.spin-r{position:absolute;inset:0;width:100%;height:100%;animation:spin 16s linear infinite}
@keyframes spin{to{transform:rotate(360deg)}}
.spin-r text{font-family:var(--fd);font-weight:800;font-size:13.4px;letter-spacing:.14em;fill:#fff;text-transform:uppercase}
.spin-c{position:absolute;inset:30px;border-radius:50%;background:linear-gradient(180deg,var(--red-l),var(--red-d));display:grid;place-items:center;box-shadow:0 14px 30px -10px rgba(226,16,25,.9)}
.spin-c svg{width:24px;height:24px;color:#fff}

/* ============ MARQUEE ============ */
.marq{position:relative;height:56px;background:var(--red);overflow:hidden;overflow-x:clip}
.marq-t{position:absolute;top:0;bottom:0;left:0;display:flex;align-items:center;width:max-content;animation:scroll 38s linear infinite;will-change:transform}
@keyframes scroll{to{transform:translateX(-50%)}}
.mq-i{color:#fff;font-family:var(--fd);font-weight:800;font-size:14px;letter-spacing:.09em;padding:0 18px;white-space:nowrap;text-transform:uppercase}
.mq-i.hl{color:#2a0304}
.mq-dot{color:rgba(255,255,255,.55);font-size:7px}

/* ============ SECTION SCAFFOLD ============ */
.sec{padding-top:clamp(58px,7vw,96px);padding-bottom:clamp(58px,7vw,96px)}
.sec.alt{background:var(--paper)}
.sec.dark{background:var(--char);color:#eaf2f6}
.sec.inkbg{background:var(--ink);color:#eaf2f6;position:relative;overflow:hidden}
.shead{max-width:64ch}
.shead.ctr{margin:0 auto;text-align:center}
.sec h2{font-size:clamp(27px,3.9vw,44px);text-transform:uppercase;color:var(--ink);margin-top:16px}
.sec.dark h2,.sec.inkbg h2{color:#fff}
.shead .sub{color:var(--tx2);font-size:clamp(15px,1.5vw,17px);margin-top:14px}
.sec.dark .sub,.sec.inkbg .sub{color:#a9b9c3}
.shead-row{display:flex;align-items:flex-end;justify-content:space-between;gap:28px;flex-wrap:wrap}

/* ============ KPI COUNTERS ============ */
@property --q1{syntax:'<integer>';initial-value:0;inherits:false}
@property --q2{syntax:'<integer>';initial-value:0;inherits:false}
@property --q3{syntax:'<integer>';initial-value:0;inherits:false}
@property --q4{syntax:'<integer>';initial-value:0;inherits:false}
.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1px;background:var(--line-d);border-radius:14px;overflow:hidden;box-shadow:var(--sh2)}
.kpi{background:var(--char);padding:30px 24px;position:relative;transition:.25s;min-width:0}
.kpi:hover{background:var(--char2)}
.kpi::before{content:"";position:absolute;left:0;top:0;width:100%;height:3px;background:var(--red);transform:scaleX(0);transform-origin:left;transition:.35s}
.kpi:hover::before{transform:scaleX(1)}
.kpi-ic{width:44px;height:44px;border-radius:11px;background:rgba(226,16,25,.14);border:1px solid rgba(226,16,25,.36);display:grid;place-items:center;margin-bottom:16px}
.kpi-ic svg{width:21px;height:21px;color:var(--red-l)}
.kpi-n{font-family:var(--fd);font-weight:900;font-size:clamp(32px,4vw,46px);color:#fff;line-height:1;letter-spacing:-.03em}
.kpi-n .cnum::after{font-variant-numeric:tabular-nums}
.c1{counter-reset:q var(--q1);animation:run1 2.6s cubic-bezier(.2,.9,.3,1) forwards}
.c2{counter-reset:q var(--q2);animation:run2 2.6s cubic-bezier(.2,.9,.3,1) forwards}
.c3{counter-reset:q var(--q3);animation:run3 2.6s cubic-bezier(.2,.9,.3,1) forwards}
.c4{counter-reset:q var(--q4);animation:run4 2.6s cubic-bezier(.2,.9,.3,1) forwards}
.c1::after,.c2::after,.c3::after,.c4::after{content:counter(q)}
@keyframes run1{to{--q1:300}}
@keyframes run2{to{--q2:40}}
@keyframes run3{to{--q3:20}}
@keyframes run4{to{--q4:8}}
.kpi b{display:block;font-family:var(--fd);font-size:13.5px;letter-spacing:.09em;text-transform:uppercase;color:#fff;margin-top:12px}
.kpi>span{font-size:13px;color:#90a1ad;display:block;margin-top:3px}
.kpi-n .cnum{font:inherit;color:inherit;display:inline}

/* ============ ABOUT SPLIT ============ */
.ab>*{min-width:0}
.ab{display:grid;grid-template-columns:minmax(0,.95fr) minmax(0,1.05fr);gap:clamp(34px,5vw,64px);align-items:center}
.ab-vis{position:relative;min-width:0}
.ab-a{clip-path:polygon(0 0,100% 0,92% 100%,0 100%);overflow:hidden;aspect-ratio:4/3.1;box-shadow:var(--sh2)}
.ab-a img{width:100%;height:100%;object-fit:cover}
.ab-b{position:absolute;right:-10px;bottom:-38px;width:52%;clip-path:polygon(8% 0,100% 0,100% 100%,0 100%);overflow:hidden;aspect-ratio:4/3;border:6px solid #fff;box-shadow:var(--sh2);background:#fff}
.ab-b img{width:100%;height:100%;object-fit:cover}
.ab-gear{position:absolute;left:-26px;top:-26px;width:86px;height:86px;color:rgba(226,16,25,.22);animation:spin 22s linear infinite;z-index:-1}
.ab-gear svg{width:86px;height:86px}
.ab-list{list-style:none;display:grid;gap:14px;margin-top:26px}
.ab-list li{display:flex;align-items:flex-start;gap:12px;font-size:15.5px;font-weight:600;color:var(--tx)}
.ab-list .ck{width:24px;height:24px;border-radius:7px;background:var(--red);color:#fff;display:grid;place-items:center;flex-shrink:0;margin-top:1px}
.ab-list .ck svg{width:13px;height:13px}
.ab-cta{display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-top:30px}
.ab-ph{display:inline-flex;align-items:center;gap:12px}
.ab-ph .ph-ic{width:48px;height:48px;border-radius:50%;background:rgba(10,99,245,.12);border:1px solid rgba(10,99,245,.34);display:grid;place-items:center;color:var(--blue-d);animation:ring 2.4s ease-in-out infinite}
@keyframes ring{0%,100%{box-shadow:0 0 0 0 rgba(10,99,245,.4)}70%{box-shadow:0 0 0 14px rgba(10,99,245,0)}}
.ab-ph small{display:block;font-size:11.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--tx2);font-weight:700}
.ab-ph b{font-family:var(--fd);font-size:18px;color:var(--ink)}

/* ============ VEHICLE GRID ============ */
.veh>*{min-width:0}
.veh{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px;margin-top:46px}
.vc{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;transition:.28s;display:flex;flex-direction:column;position:relative}
.vc::after{content:"";position:absolute;left:0;bottom:0;height:4px;width:100%;background:var(--red);transform:scaleX(0);transform-origin:left;transition:.35s}
.vc:hover{transform:translateY(-8px);box-shadow:0 26px 52px -22px rgba(10,99,245,.5);border-color:transparent}
.vc:hover::after{transform:scaleX(1)}
.vc-img{aspect-ratio:16/11;background:var(--char2);overflow:hidden;position:relative}
.vc-img img{width:100%;height:100%;object-fit:cover;transition:.55s}
.vc:hover .vc-img img{transform:scale(1.09)}
.vc-tag{position:absolute;left:14px;top:14px;background:rgba(7,10,14,.84);color:#fff;font-family:var(--fd);font-weight:800;font-size:10.5px;letter-spacing:.12em;text-transform:uppercase;padding:7px 11px;border-radius:6px;backdrop-filter:blur(4px)}
.vc-b{padding:20px 22px 24px}
.vc-b h3{font-size:19px;color:var(--ink)}
.vc-b p{font-size:14px;color:var(--tx2);margin-top:9px}
.vc-b .vl{display:inline-flex;align-items:center;gap:7px;margin-top:16px;color:var(--red);font-weight:800;font-family:var(--fd);font-size:11.5px;letter-spacing:.09em;text-transform:uppercase;cursor:pointer}
.vc-b .vl svg{width:14px;height:14px;transition:.25s}
.vc:hover .vl svg{transform:translateX(5px)}

/* ============ SERVICE CARDS ============ */
.svc>*{min-width:0}
.svc{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin-top:46px}
.sc{position:relative;border-radius:16px;overflow:hidden;background:var(--ink);min-height:420px;display:flex;align-items:flex-end;transition:.3s;isolation:isolate}
.sc img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2;transition:.6s}
.sc::before{content:"";position:absolute;inset:0;z-index:-1;background:linear-gradient(to top,rgba(5,8,11,.96) 6%,rgba(5,8,11,.6) 46%,rgba(5,8,11,.18) 100%);transition:.35s}
.sc:hover{transform:translateY(-8px);box-shadow:0 30px 60px -24px rgba(9,15,20,.8)}
.sc:hover img{transform:scale(1.08)}
.sc:hover::before{background:linear-gradient(to top,rgba(140,8,13,.94) 6%,rgba(10,14,19,.72) 50%,rgba(10,14,19,.2) 100%)}
.sc-b{padding:28px 26px 30px;width:100%}
.sc-n{font-family:var(--fd);font-weight:900;font-size:40px;color:rgba(255,255,255,.22);line-height:1;letter-spacing:-.04em}
.sc-b h3{font-size:22px;color:#fff;margin-top:10px;text-transform:uppercase}
.sc-b p{font-size:14.5px;color:#c3d0d8;margin-top:12px;max-height:0;opacity:0;overflow:hidden;transition:.4s}
.sc:hover p{max-height:140px;opacity:1;margin-top:12px}
.sc-b .more{display:inline-flex;align-items:center;gap:8px;margin-top:18px;color:#fff;font-weight:800;font-family:var(--fd);font-size:12px;letter-spacing:.1em;text-transform:uppercase;cursor:pointer}
.sc-b .more i{width:34px;height:34px;border-radius:50%;background:var(--red);display:grid;place-items:center;transition:.25s}
.sc-b .more i svg{width:15px;height:15px}
.sc:hover .more i{background:#fff;color:var(--red)}

/* ============ PRICE BEAT ============ */
.pbeat{background:linear-gradient(100deg,var(--red-d),var(--red) 52%,#ff4b52);color:#fff;position:relative;overflow:hidden}
.pbeat::after{content:"";position:absolute;inset:0;background:radial-gradient(60% 160% at 100% 50%,rgba(255,255,255,.22),transparent 60%)}
.pbeat::before{content:"";position:absolute;top:0;left:-45%;width:34%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.32),transparent);transform:skewX(-20deg);animation:shine 6.5s ease-in-out infinite;z-index:1}
@keyframes shine{0%,52%{left:-45%}100%{left:155%}}
.pbeat-in{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:26px;flex-wrap:wrap;padding-top:30px;padding-bottom:30px}
.pbeat .pb-l{display:flex;align-items:center;gap:18px;min-width:0}
.pbeat .pb-ic{width:58px;height:58px;border-radius:14px;background:rgba(255,255,255,.18);display:grid;place-items:center;flex-shrink:0}
.pbeat .pb-ic svg{width:28px;height:28px;color:#fff}
.pbeat h3{font-size:clamp(21px,2.7vw,29px);color:#fff;text-transform:uppercase}
.pbeat p{color:rgba(255,255,255,.95);font-weight:500;font-size:14.5px;margin-top:5px}

/* ============ PROCESS ============ */
.proc>*{min-width:0}
.proc{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:26px;margin-top:48px}
.pr{background:var(--char);border:1px solid var(--line-d);border-radius:16px;padding:32px 28px 34px;position:relative;overflow:hidden;transition:.28s}
.pr:hover{transform:translateY(-7px);border-color:var(--red);box-shadow:0 26px 54px -24px rgba(226,16,25,.45)}
.pr-n{position:absolute;right:16px;top:4px;font-family:var(--fd);font-weight:900;font-size:86px;color:rgba(255,255,255,.055);line-height:1}
.pr-ic{width:60px;height:60px;border-radius:15px;background:rgba(10,99,245,.14);border:1px solid rgba(10,99,245,.38);display:grid;place-items:center;transition:.28s}
.pr-ic svg{width:27px;height:27px;color:var(--blue-l);transition:.28s}
.pr:hover .pr-ic{background:var(--red);border-color:var(--red)}
.pr:hover .pr-ic svg{color:#fff}
.pr h4{font-size:19px;color:#fff;margin-top:22px;text-transform:uppercase}
.pr p{font-size:14.5px;color:#a2b2bd;margin-top:10px}

/* ============ ENGINE ASSEMBLY ============ */
.asm-sec{position:relative;overflow:hidden;background:radial-gradient(130% 120% at 50% -15%,#141d26,var(--ink) 62%);color:#eaf2f6}
.asm-sec h2{color:#fff}.asm-sec .sub{color:#a9b9c3}
.engine{position:relative;width:min(600px,100%);margin:24px auto 4px;aspect-ratio:7/5}
.engine .part{position:absolute;display:block}
.engine .part svg{width:100%;height:auto;display:block;overflow:visible}
.blk{left:13%;top:31%;width:74%;z-index:1}
.pis{width:8.4%;z-index:0}
.p1{left:24.6%;top:15%}.p2{left:38.3%;top:15%}.p3{left:52%;top:15%}.p4{left:65.7%;top:15%}
.cover{left:19%;top:21%;width:62%;z-index:3}
.intake{left:59%;top:33%;width:34%;z-index:2}
.e-alt{left:3%;top:52%;width:21%;z-index:2}
.turbo{left:62%;top:58%;width:26%;z-index:2}
.tag{position:absolute;font-family:var(--fd);font-weight:800;font-size:11px;letter-spacing:.06em;padding:6px 12px;border-radius:999px;z-index:4;white-space:nowrap;text-transform:uppercase}
.tag-r{left:50%;top:1%;transform:translateX(-50%);background:rgba(10,99,245,.16);border:1px solid rgba(10,99,245,.5);color:#8fb9ff}
.tag-a{right:2%;bottom:3%;background:rgba(226,16,25,.16);border:1px solid rgba(226,16,25,.5);color:#ff8a8e}
.p1{animation:ep1 12s ease-in-out infinite}.p2{animation:ep2 12s ease-in-out infinite}
.p3{animation:ep3 12s ease-in-out infinite}.p4{animation:ep4 12s ease-in-out infinite}
.cover{animation:ecov 12s ease-in-out infinite}.intake{animation:eintk 12s ease-in-out infinite}
.e-alt{animation:ealt 12s ease-in-out infinite}.turbo{animation:etrb 12s ease-in-out infinite}
@keyframes ep1{0%,5%{transform:translateY(-520%);opacity:0}11%,90%{transform:translateY(0);opacity:1}100%{transform:translateY(-520%);opacity:0}}
@keyframes ep2{0%,8%{transform:translateY(-520%);opacity:0}14%,90%{transform:translateY(0);opacity:1}100%{transform:translateY(-520%);opacity:0}}
@keyframes ep3{0%,11%{transform:translateY(-520%);opacity:0}17%,90%{transform:translateY(0);opacity:1}100%{transform:translateY(-520%);opacity:0}}
@keyframes ep4{0%,14%{transform:translateY(-520%);opacity:0}20%,90%{transform:translateY(0);opacity:1}100%{transform:translateY(-520%);opacity:0}}
@keyframes ecov{0%,27%{transform:translateY(-300%);opacity:0}37%,90%{transform:translateY(0);opacity:1}100%{transform:translateY(-300%);opacity:0}}
@keyframes eintk{0%,41%{transform:translateX(180%);opacity:0}51%,90%{transform:translateX(0);opacity:1}100%{transform:translateX(180%);opacity:0}}
@keyframes ealt{0%,55%{transform:translateX(-260%);opacity:0}65%,90%{transform:translateX(0);opacity:1}100%{transform:translateX(-260%);opacity:0}}
@keyframes etrb{0%,67%{transform:translate(170%,160%);opacity:0}77%,90%{transform:translate(0,0);opacity:1}100%{transform:translate(170%,160%);opacity:0}}
.asm-legend{display:flex;gap:28px;justify-content:center;flex-wrap:wrap;margin-top:10px}
.asm-legend .lg{display:inline-flex;align-items:center;gap:10px;font-size:14px;color:#c0ced7}
.asm-legend .sw{width:28px;height:16px;border-radius:5px;flex-shrink:0}
.sw-r{background:linear-gradient(180deg,#eef3f8,#9aa7b4);border:1px solid #5a93f2}
.sw-a{background:linear-gradient(180deg,#ff2a31,#c00d14)}
.asm-note{text-align:center;color:#a9b9c3;max-width:64ch;margin:18px auto 0;font-size:15px}

/* ============ FLEX SOLUTIONS ============ */
.flex2>*{min-width:0}
.flex2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:26px;margin-top:46px}
.fx{background:#fff;border:1px solid var(--line);border-radius:16px;overflow:hidden;box-shadow:var(--sh);display:flex;flex-direction:column;transition:.26s}
.fx:hover{transform:translateY(-6px);box-shadow:0 26px 56px -22px rgba(10,99,245,.42)}
.fx-img{aspect-ratio:16/7;overflow:hidden;background:var(--char2);position:relative}
.fx-img img{width:100%;height:100%;object-fit:cover;transition:.55s}
.fx:hover .fx-img img{transform:scale(1.07)}
.fx-top{display:flex;align-items:center;gap:16px;padding:24px 26px 0}
.fx-ic{width:52px;height:52px;border-radius:13px;background:var(--ink);display:grid;place-items:center;flex-shrink:0}
.fx-ic svg{width:24px;height:24px;color:var(--red-l)}
.fx-top h3{font-size:20px;color:var(--ink);text-transform:uppercase}
.fx ul{list-style:none;padding:18px 26px 26px;display:grid;gap:12px}
.fx li{display:flex;align-items:flex-start;gap:11px;font-size:14.5px;color:var(--tx)}
.fx li .ck{width:22px;height:22px;border-radius:50%;background:rgba(226,16,25,.12);color:var(--red);display:grid;place-items:center;flex-shrink:0;margin-top:1px}
.fx li .ck svg{width:13px;height:13px}
.fx .fx-cta{margin:0 26px 26px}

/* ============ REVIEWS + FAQ ============ */
.rf>*{min-width:0}
.rf{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:48px;align-items:start}
.rf h2{font-size:clamp(23px,2.9vw,32px);color:var(--ink);text-transform:uppercase;margin-top:16px}
.rf .mini{color:var(--tx2);font-size:14.5px;margin-top:11px}
.revs>*{min-width:0}
.revs{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;margin-top:24px}
.rev{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;box-shadow:var(--sh);position:relative;transition:.25s}
.rev:hover{transform:translateY(-5px);border-color:var(--red)}
.rev .st{display:flex;gap:2px;color:#f5a623;margin-bottom:12px}.rev .st svg{width:15px;height:15px}
.rev q{font-size:13.5px;color:var(--tx);line-height:1.58;quotes:none;display:block}
.rev figcaption{display:flex;align-items:center;gap:10px;margin-top:16px;padding-top:15px;border-top:1px solid var(--line)}
.rev .av{width:38px;height:38px;border-radius:50%;background:linear-gradient(145deg,var(--red-l),var(--red-d));color:#fff;display:grid;place-items:center;font-family:var(--fd);font-weight:800;font-size:15px;flex-shrink:0}
.rev figcaption b{font-size:13.5px;color:var(--ink);display:block}
.rev figcaption small{font-size:12px;color:var(--tx2)}
.faqs{margin-top:24px}
.faq{border:1px solid var(--line);border-radius:12px;margin-bottom:11px;background:#fff;transition:.2s}
.faq[open]{box-shadow:var(--sh);border-color:var(--red)}
.faq summary{list-style:none;cursor:pointer;padding:17px 19px;font-family:var(--fd);font-weight:700;font-size:15px;color:var(--ink);display:flex;align-items:center;justify-content:space-between;gap:14px}
.faq summary::-webkit-details-marker{display:none}
.faq-x{position:relative;width:16px;height:16px;flex-shrink:0}
.faq-x::before,.faq-x::after{content:"";position:absolute;background:var(--red);border-radius:2px;transition:.25s}
.faq-x::before{top:7px;left:0;width:16px;height:2.2px}.faq-x::after{left:7px;top:0;width:2.2px;height:16px}
.faq[open] .faq-x::after{transform:rotate(90deg);opacity:0}
.faq-a{padding:0 19px 19px}.faq-a p{font-size:14px;color:var(--tx2)}

/* ============ CTA BAND ============ */
.cta{position:relative;background:linear-gradient(100deg,var(--ink) 0%,#101821 55%,var(--ink) 100%);color:#fff;overflow:hidden}
.cta::before{content:"";position:absolute;inset:0;background:radial-gradient(50% 130% at 78% 50%,rgba(226,16,25,.3),transparent 62%)}
.cta-in{position:relative;z-index:2;padding-top:clamp(56px,6.4vw,86px);padding-bottom:clamp(56px,6.4vw,86px)}
.cta h2{font-size:clamp(29px,4.5vw,50px);color:#fff;text-transform:uppercase;line-height:.97;max-width:17ch;margin-top:18px}
.cta p{color:#b9c7d0;font-size:clamp(15px,1.7vw,18px);margin-top:18px;max-width:52ch}
.cta-btns{display:flex;gap:14px;flex-wrap:wrap;margin-top:30px}
.cta-trust{display:flex;gap:24px;flex-wrap:wrap;margin-top:32px}
.cta-trust .ct{display:inline-flex;align-items:center;gap:8px;font-size:13.5px;color:#cbd7de;font-weight:600}
.cta-trust svg{width:17px;height:17px;color:var(--red-l)}

/* ============ FOOTER ============ */
footer{background:var(--ink);color:#99a9b5;padding-top:64px}
.foot-grid>*{min-width:0}
.foot-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr) minmax(0,1.2fr) minmax(0,1.1fr);gap:38px;padding-bottom:44px;border-bottom:1px solid var(--line-d)}
.foot-brand img{height:52px;width:auto;max-width:100%;margin-bottom:18px}
.foot-brand p{font-size:13.5px;color:#7d8e9b;max-width:38ch}
.foot-soc{display:flex;gap:10px;margin-top:20px}
.foot-soc a{width:38px;height:38px;border-radius:10px;background:var(--char2);display:grid;place-items:center;color:#aebdc6;transition:.2s}
.foot-soc a:hover{background:var(--red);color:#fff;transform:translateY(-3px)}
.foot-soc svg{width:17px;height:17px}
.foot-h{font-family:var(--fd);font-weight:800;color:#fff;font-size:13px;letter-spacing:.12em;text-transform:uppercase;margin-bottom:18px;position:relative;padding-bottom:12px}
.foot-h::after{content:"";position:absolute;left:0;bottom:0;width:30px;height:2px;background:var(--red)}
.foot-ul{list-style:none;display:grid;gap:10px}
.foot-ul a{font-size:14px;color:#99a9b5;transition:.15s}.foot-ul a:hover{color:var(--red-l);padding-left:4px}
.foot-c{display:grid;gap:12px}
.foot-c a,.foot-c span{display:flex;gap:10px;align-items:flex-start;font-size:14px;color:#99a9b5}
.foot-c a:hover{color:#fff}
.foot-c svg{width:17px;height:17px;color:var(--red-l);margin-top:2px}
.aus-wrap{display:flex;gap:8px;align-items:flex-start}
.aus{width:92px;height:auto;flex-shrink:0}
.aus-wrap p{font-size:13px;color:#7d8e9b}
.foot-bot{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;padding:22px 0 30px}
.foot-bot small{font-size:12.5px;color:#697986}
.foot-bot .fl{display:flex;gap:16px;flex-wrap:wrap}
.foot-bot .fl a{font-size:12.5px;color:#8597a3}.foot-bot .fl a:hover{color:var(--red-l)}
.built{display:inline-flex;align-items:center;gap:9px;font-size:13px;color:#99a9b5}
.built b{color:#f0b429}.built-ico{width:30px;height:30px;border-radius:8px}

/* ============ SLIDE-OUT QUOTE SIDEBAR ============ */
.sq-ov{position:fixed;inset:0;background:rgba(4,7,10,.74);backdrop-filter:blur(4px);opacity:0;visibility:hidden;transition:opacity .35s,visibility .35s;z-index:88;cursor:pointer}
#sideq:checked ~ .sq-ov{opacity:1;visibility:visible}

@keyframes spark{0%,100%{opacity:.35;transform:translateX(-50%) scale(.75)}50%{opacity:1;transform:translateX(-50%) scale(1.15)}}
@keyframes nudge{0%,100%{transform:translateX(0)}50%{transform:translateX(-5px)}}
.sq-panel{position:fixed;right:0;top:0;height:100%;z-index:90;width:min(442px,100%);background:var(--paper);box-shadow:-30px 0 80px -24px rgba(4,7,10,.7);transform:translateX(100%);visibility:hidden;transition:transform .42s cubic-bezier(.4,0,.1,1),visibility .42s;overflow-y:auto;overscroll-behavior:contain}
#sideq:checked ~ .sq-panel{transform:translateX(0);visibility:visible}
.sq-close{position:absolute;top:14px;right:14px;width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);color:#fff;display:grid;place-items:center;cursor:pointer;z-index:3;transition:.2s}
.sq-close:hover{background:var(--red);border-color:var(--red);transform:rotate(90deg)}
.sq-close svg{width:16px;height:16px}
.sq-head{position:relative;background:radial-gradient(120% 130% at 100% 0%,#152029,var(--ink));color:#fff;padding:26px 24px 24px;overflow:hidden}
.sq-head::after{content:"";position:absolute;right:-50px;top:-50px;width:190px;height:190px;border-radius:50%;background:radial-gradient(circle,rgba(226,16,25,.34),transparent 68%)}
.sq-head-in{position:relative;z-index:2;display:flex;align-items:center;gap:14px}
.sq-head-ic{width:56px;height:56px;border-radius:14px;background:rgba(226,16,25,.16);border:1px solid rgba(226,16,25,.4);display:grid;place-items:center;flex-shrink:0}
.sq-head-ic svg{width:30px;height:30px;color:var(--red-l);animation:spin 9s linear infinite}
.sq-kick{display:inline-block;font-family:var(--fd);font-weight:800;font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--red-l);margin-bottom:8px}
.sq-head h3{font-size:22px;text-transform:uppercase;line-height:1.05}
.sq-head p{font-size:13.5px;color:#a9b9c3;margin-top:12px;position:relative;z-index:2}
.sq-strip{display:flex;gap:8px;flex-wrap:wrap;padding:14px 24px;background:var(--ink2);border-bottom:1px solid rgba(255,255,255,.07)}
.sq-strip span{display:inline-flex;align-items:center;gap:6px;font-size:11.5px;font-weight:700;color:#bdcad3;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);padding:6px 11px;border-radius:999px}
.sq-strip svg{width:13px;height:13px;color:var(--red-l)}
.sq-form{display:grid;gap:12px;padding:22px 24px 26px}
.sq-l{font-size:12px;font-weight:700;color:var(--tx2);letter-spacing:.04em;text-transform:uppercase;margin-bottom:6px;display:block}
.sq-f{min-width:0}
.sq-f input,.sq-f select,.sq-f textarea{min-width:0;width:100%;font:inherit;font-size:15px;padding:13px 14px;border:1.5px solid var(--line);border-radius:10px;background:#fff;color:var(--tx);appearance:none;transition:.2s}
.sq-f select{background-image:linear-gradient(45deg,transparent 50%,#55646f 50%),linear-gradient(135deg,#55646f 50%,transparent 50%);background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;background-size:6px 6px,6px 6px;background-repeat:no-repeat}
.sq-f select option{background:#fff;color:var(--tx)}
.sq-f input:focus,.sq-f select:focus,.sq-f textarea:focus{outline:none;border-color:var(--red);box-shadow:0 0 0 3px rgba(226,16,25,.14)}
.sq-f textarea{resize:vertical;min-height:76px}
.sq-2{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:12px}
.sq-2>*{min-width:0}
.sq-form .btn{width:100%;justify-content:center;margin-top:4px}
.sq-fine{font-size:11.5px;color:var(--tx2);display:flex;align-items:center;justify-content:center;gap:6px;margin-top:4px}
.sq-fine svg{width:14px;height:14px;color:var(--red)}
.sq-foot{background:var(--ink);color:#a9b9c3;padding:20px 24px 26px;margin-top:auto}
.sq-foot small{display:block;font-size:11px;letter-spacing:.14em;text-transform:uppercase;font-weight:800;color:#7d8e9b;margin-bottom:8px}
.sq-foot a.sq-ph{display:inline-flex;align-items:center;gap:10px;font-family:var(--fd);font-weight:900;font-size:23px;color:#fff}
.sq-foot a.sq-ph svg{width:20px;height:20px;color:var(--red-l)}
.sq-foot p{font-size:12.5px;margin-top:10px;color:#7d8e9b}

/* ============ MOBILE BAR + TOTOP ============ */
.mbar{display:none;position:fixed;left:0;right:0;bottom:0;z-index:70;background:rgba(7,10,14,.97);border-top:1px solid var(--line-d);padding:9px 12px;gap:10px}
.mbar a,.mbar label{flex:1;display:flex;align-items:center;justify-content:center;gap:8px;font-family:var(--fd);font-weight:800;font-size:14px;padding:13px;border-radius:10px;cursor:pointer;text-transform:uppercase;letter-spacing:.03em}
.mbar .m-call{background:var(--char3);color:#fff}.mbar .m-quote{background:linear-gradient(180deg,var(--red-l),var(--red-d));color:#fff}
.mbar svg{width:17px;height:17px}
.totop{position:fixed;right:18px;bottom:20px;z-index:65;width:46px;height:46px;border-radius:50%;background:var(--ink);color:#fff;display:grid;place-items:center;box-shadow:var(--sh2);border:1px solid var(--line-d)}
.totop svg{width:20px;height:20px}

/* ============ RESPONSIVE ============ */
@media(min-width:1281px){header{overflow-x:clip}}

@media(max-width:1280px){
 .nav{position:fixed;top:0;right:0;height:100vh;height:100dvh;width:min(338px,86vw);background:#0a0e13;flex-direction:column;align-items:stretch;gap:0;padding:92px 26px 30px;margin:0;box-shadow:var(--sh2);clip-path:inset(0 0 0 100%);pointer-events:none;transition:clip-path .3s;overflow-y:auto;z-index:62}
 .nav a.nl{padding:15px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:16px;color:#e7edf3}
 .nav .hdr-cta{margin-top:20px;justify-content:center}
 .nav .m-ph{display:inline-flex;align-items:center;justify-content:center;gap:8px;margin-top:16px;font-family:var(--fd);font-weight:800;font-size:18px;color:#eef3f8}
 .nav .m-ph svg{width:18px;height:18px;color:var(--red-l)}
 #mtog:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto}
 #mtog:checked ~ .burger span{background:transparent}
 #mtog:checked ~ .burger span::before{top:0;transform:rotate(45deg)}
 #mtog:checked ~ .burger span::after{top:0;transform:rotate(-45deg)}
 .burger{display:inline-flex;position:relative;z-index:63}
 .kpis{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
 .veh{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
 .svc{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}
 .proc{grid-template-columns:minmax(0,1fr)}
}
@media(max-width:980px){
 .hero-in{grid-template-columns:minmax(0,1fr);gap:42px}
 .hvis{max-width:560px}
 .ab{grid-template-columns:minmax(0,1fr);gap:64px}
 .ab-b{width:46%;right:0;bottom:-30px}
 .flex2{grid-template-columns:minmax(0,1fr)}
 .rf{grid-template-columns:minmax(0,1fr);gap:40px}
 .foot-grid{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:30px}
}
@media(max-width:900px){
 .util .u-r{display:none}
 .util-in{justify-content:center}
 .util .u-l{gap:16px}
 .util .u-l>*:not(.u-keep):not(:first-child){display:none}
}
@media(max-width:720px){
 .util .u-r{display:none}
 .util-in{justify-content:center}
 .util .u-l>*:not(.u-keep){display:none}
 .eyb{font-size:11px;letter-spacing:.13em;padding:7px 14px 7px 11px}
 .veh{grid-template-columns:minmax(0,1fr)}
 .svc{grid-template-columns:minmax(0,1fr)}
 .sc{min-height:340px}
 .sc-b p{max-height:140px;opacity:1}
 .revs{grid-template-columns:minmax(0,1fr)}
 .pbeat-in{flex-direction:column;align-items:flex-start}
 .mbar{display:flex}.totop{display:none}.sq-tab{display:none}
 body{padding-bottom:72px}
 .sq-panel{width:100%}
 .spin{width:98px;height:98px;right:-6px;bottom:-18px}
}
@media(max-width:560px){
 .btn{white-space:normal;text-align:center;line-height:1.25;padding:15px 20px;justify-content:center}
 .ab-cta,.hero-cta,.cta-btns{width:100%}
 .ab-cta>.btn,.hero-cta>.btn,.cta-btns>.btn{flex:1 1 100%}
 .pbeat .btn{white-space:normal}
}
