 radial-gradient(circle at 11px calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px),
 radial-gradient(circle at calc(100% - 11px) calc(100% - 11px),#9db0bf 0 2.3px,#3a4a5a 2.5px 3.6px,rgba(0,0,0,.45) 3.7px 4.4px,transparent 4.5px);
