header{position:sticky;top:calc(0px - var(--utilh));z-index:60;background:transparent;border:0}
.hdr-bar{background:#070a0e;border-bottom:1px solid rgba(255,255,255,.08)}
.hdr-in{display:flex;align-items:center;gap:22px;min-height:80px}
.brand{flex-shrink:0;display:block;line-height:0}
